import {snapshot,summarize,compare,metrics,readHistory,writeHistory,comparisonCSV} from './analysis-history.js';
export function createHistoryUI(getResult){
 const dialog=document.createElement('dialog');dialog.id='analysis-history';dialog.setAttribute('aria-labelledby','history-title');dialog.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">DESIGN RESEARCH</span><h2 id="history-title">Saved analysis results</h2></div><button class="icon" data-close aria-label="Close saved results">×</button></div><p>Save a completed run, change your form and calculate again. Compare the sample means against a baseline.</p><div class="history-actions"><label>Run name <input data-name maxlength="100" placeholder="e.g. Tapered tower · option B"></label><button class="button dark" data-save>Save current result</button></div><p data-status role="status" aria-live="polite"></p><div class="history-actions"><label>Baseline <select data-baseline></select></label><button class="button" data-csv>Export comparison CSV</button><button class="button" data-json>Export full results JSON</button></div><p class="note">Saved on this browser, up to 12 runs. Export JSON for a durable backup of projects, settings, weather and point results. Surface points move with the design: mean differences are not point-by-point changes or whole-building energy. A positive change is not necessarily an improvement. Percentage metrics use percentage-point deltas.</p><div data-table class="history-table" tabindex="0" aria-label="Saved results comparison"></div>`;document.body.append(dialog);
 const $=s=>dialog.querySelector(s);let runs=[],baseline='',storage,error='';try{storage=window.localStorage;runs=readHistory(storage);}catch(e){error='Saved results unavailable: '+e.message;}let readable=!error;
 function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 function cell(row,text,tag='td'){const el=document.createElement(tag);el.textContent=text;row.append(el);return el;}
 function render(){if(!runs.some(r=>r.id===baseline))baseline=runs[0]?.id||'';const base=runs.find(r=>r.id===baseline);$('[data-baseline]').replaceChildren(...runs.map(r=>new Option(r.name,r.id)));$('[data-baseline]').value=baseline;$('[data-baseline]').disabled=!runs.length;$('[data-csv]').disabled=!runs.length;$('[data-json]').disabled=!runs.length;$('[data-save]').disabled=!getResult()||!readable||runs.length>=12;$('[data-status]').textContent=error||`${runs.length} of 12 saved runs. ${getResult()?'Current result ready to save.':'Calculate an analysis to save a new result.'}`;
 const holder=$('[data-table]');holder.replaceChildren();if(!runs.length){holder.textContent='No saved results yet.';return;}const table=document.createElement('table'),head=document.createElement('thead'),hr=document.createElement('tr');for(const label of ['Run / settings','Metric','Min / mean / max','Change from baseline','Actions'])cell(hr,label,'th');head.append(hr);table.append(head);const body=document.createElement('tbody');
 for(const run of runs){const row=document.createElement('tr'),r=run.result,s=summarize(r.values),c=compare(run,base),[title,unit]=metrics[r.settings.analysis],info=cell(row,run.name+(run.id===baseline?' · baseline':''));const date=document.createElement('small');date.textContent=new Date(run.savedAt).toLocaleString();info.append(date);const detail=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent=`${s.count} samples · ${r.settings.target} · settings`;pre.textContent=JSON.stringify({engine:run.engine,settings:r.settings,weather:r.weather?{source:r.weather.source,retrieved:r.weather.retrieved,gridLatitude:r.weather.gridLatitude,gridLongitude:r.weather.gridLongitude}:null},null,2);detail.append(summary,pre);info.append(detail);cell(row,title+' ('+unit+')');cell(row,[s.min,s.mean,s.max].map(v=>v.toFixed(2)).join(' / '));cell(row,c.reasons.length?'Not comparable: '+c.reasons.join(', '):(c.delta>=0?'+':'')+c.delta.toFixed(2)+' '+(unit==='%'?'percentage points':unit)+(c.relative===null?'':` (${c.relative>=0?'+':''}${c.relative.toFixed(1)}% relative)`));const actions=cell(row,'');const remove=document.createElement('button');remove.className='button';remove.textContent='Delete';remove.setAttribute('aria-label','Delete '+run.name);remove.onclick=()=>{try{const next=runs.filter(v=>v.id!==run.id);writeHistory(storage,next);runs=next;error='';render();}catch(e){error='Could not delete: '+e.message;render();}};actions.append(remove);body.append(row);}table.append(body);holder.append(table);}
 $('[data-close]').onclick=()=>dialog.close();$('[data-baseline]').onchange=e=>{baseline=e.target.value;render();};$('[data-save]').onclick=()=>{try{const result=getResult();if(!result)return;const next=[...runs,snapshot(result,$('[data-name]').value||`Option ${runs.length+1} · ${metrics[result.settings.analysis][0]}`)];writeHistory(storage,next);runs=next;error='';$('[data-name]').value='';render();}catch(e){error='Result was not saved: '+e.message+' Export the current analysis CSV or free browser storage and retry.';render();}};
 $('[data-csv]').onclick=()=>download(comparisonCSV(runs,runs.find(r=>r.id===baseline)),'text/csv','form-analysis-comparison.csv');$('[data-json]').onclick=()=>download(JSON.stringify({schema:'form-analysis-history-v1',runs},null,2),'application/json','form-analysis-results.json');
 return {open(){render();dialog.showModal();}};
}
